create table if not exists public.event_analytics_daily(event_id uuid not null references public.events(id) on delete cascade,day date not null,views bigint not null default 0,unique_visitors bigint not null default 0,vote_starts bigint not null default 0,successful_votes bigint not null default 0,primary key(event_id,day));
alter table public.event_analytics_daily enable row level security;
create policy analytics_member_read on public.event_analytics_daily for select to authenticated using(exists(select 1 from public.events e where e.id=event_id and private.is_org_member(e.organization_id)));
revoke insert,update,delete on public.event_analytics_daily from anon,authenticated; grant select on public.event_analytics_daily to authenticated; grant all on public.event_analytics_daily to service_role;
create table if not exists private.event_analytics_visitors(event_id uuid not null references public.events(id) on delete cascade,day date not null,visitor_hash text not null,primary key(event_id,day,visitor_hash));
revoke all on private.event_analytics_visitors from public,anon,authenticated;
create or replace function public.record_event_view(p_event_id uuid,p_visitor_hash text) returns void language plpgsql security definer set search_path='' as $$ declare d date:=current_date; inserted boolean; begin if p_visitor_hash is null or char_length(p_visitor_hash)<16 or char_length(p_visitor_hash)>128 then raise exception 'Invalid visitor'; end if; if not exists(select 1 from public.events where id=p_event_id and status in ('published','paused','closed')) then return; end if; insert into private.event_analytics_visitors(event_id,day,visitor_hash) values(p_event_id,d,p_visitor_hash) on conflict do nothing returning true into inserted; insert into public.event_analytics_daily(event_id,day,views,unique_visitors) values(p_event_id,d,1,case when inserted then 1 else 0 end) on conflict(event_id,day) do update set views=event_analytics_daily.views+1,unique_visitors=event_analytics_daily.unique_visitors+excluded.unique_visitors; end $$;
revoke all on function public.record_event_view(uuid,text) from public; grant execute on function public.record_event_view(uuid,text) to anon,authenticated;
create or replace function public.get_organization_traffic(p_org uuid,p_days integer default 30) returns table(day date,views bigint,unique_visitors bigint,vote_starts bigint,successful_votes bigint) language sql stable security definer set search_path='' as $$ select a.day,a.views,a.unique_visitors,a.vote_starts,a.successful_votes from public.event_analytics_daily a join public.events e on e.id=a.event_id where e.organization_id=p_org and private.is_org_member(p_org) and a.day>=current_date-greatest(1,least(p_days,365)) order by a.day; $$;
revoke all on function public.get_organization_traffic(uuid,integer) from public,anon; grant execute on function public.get_organization_traffic(uuid,integer) to authenticated;
